use std :: fmt :: { Display , Formatter } ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use super :: operation :: PermissionOperation ; use super :: rule :: Rule ; use super :: types :: Permission ; use std :: path :: PathBuf ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: WriteRule ; impl Policy { # [doc = " Evaluate a policy against an operation"] pub fn eval (& self , operation : & PermissionOperation) -> Option < Permission > { match self { Policy :: Simple { permission , rule } => { let rule_matches = rule . matches (operation) ; if rule_matches { Some (permission . clone ()) } else { None } } Policy :: All { all : and } => { let permissions : Vec < _ > = and . iter () . map (| policy | policy . eval (operation)) . collect () ; permissions . into_iter () . find (| permission | permission . is_some ()) . flatten () } Policy :: Any { any : or } => { let permissions : Vec < _ > = or . iter () . map (| policy | policy . eval (operation)) . collect () ; permissions . into_iter () . find (| permission | permission . is_some ()) . flatten () } Policy :: Not { not } => { let inner_permission = not . eval (operation) ; match inner_permission { Some (permission) => { let inverted_permission = match permission { Permission :: Deny => Permission :: Allow , Permission :: Allow => Permission :: Deny , Permission :: Confirm => Permission :: Deny , } ; Some (inverted_permission) } None => None , } } } } # [doc = " Find all rules that match the given operation"] pub fn find_rules (& self , operation : & PermissionOperation) -> Vec < & Rule > { let mut rules = Vec :: new () ; self . collect_matching_rules (operation , & mut rules) ; rules } # [doc = " Recursively collect all matching rules"] fn collect_matching_rules < 'a > (& 'a self , operation : & PermissionOperation , rules : & mut Vec < & 'a Rule > ,) { match self { Policy :: Simple { permission : _ , rule } => { if rule . matches (operation) { rules . push (rule) ; } } Policy :: All { all : and } => { for policy in and { policy . collect_matching_rules (operation , rules) ; } } Policy :: Any { any : or } => { for policy in or { policy . collect_matching_rules (operation , rules) ; } } Policy :: Not { not } => { not . collect_matching_rules (operation , rules) ; } } } # [doc = " Get the permission for this policy if it's a simple policy"] pub fn permission (& self) -> Option < & Permission > { match self { Policy :: Simple { permission , rule : _ } => Some (permission) , _ => None , } } }